SELECT cm.Maker, ml.Model
FROM car_makers AS cm
JOIN model_list AS ml ON ml.Maker = cm.Id;

SELECT cm.Maker, ml.Model
FROM car_makers AS cm
JOIN model_list AS ml ON ml.Maker = cm.Id;

SELECT COUNT(*) AS match_count
FROM matches
WHERE year IN (2013, 2016);

SELECT COUNT(*) AS number_of_matches
FROM matches
WHERE year IN (2013, 2016);

SELECT "Record_Company", COUNT(*) AS "orchestra_count"
FROM "orchestra"
GROUP BY "Record_Company";

SELECT AVG("Age") AS average_age, MIN("Age") AS minimum_age, MAX("Age") AS maximum_age
FROM "singer"
WHERE "Country" = 'France';

SELECT COUNT(*) AS country_count
FROM country
WHERE Continent = 'Asia';

SELECT hand, COUNT(*) AS number_of_players
FROM players
GROUP BY hand;

SELECT "Directed_by", COUNT(*) AS "number_of_cartoons"
FROM "Cartoon"
GROUP BY "Directed_by";

SELECT c."Name", o."Orchestra"
FROM "conductor" AS c
JOIN "orchestra" AS o ON c."Conductor_ID" = o."Conductor_ID";

SELECT people.Name
FROM poker_player
JOIN people ON poker_player.People_ID = people.People_ID;

SELECT people.Name
FROM poker_player
JOIN people ON poker_player.People_ID = people.People_ID;
